      "content": "from __future__ import annotations

from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union


def parse_edge(line: str) -> Tuple[str, str, int]:
    """
    Parse one road record from a network file.

    A record has the form ``<FROM>-<TO>:<KM>``: two depot codes separated by a hyphen,
    then a colon and the road length in whole kilometres. Whitespace around the record
    and around each of the three parts is ignored. Depot codes are non-empty and consist
    of letters and digits only; the length is a non-negative integer.

    Returns a tuple ``(from_code, to_code, km)`` with from_code <= to_code alphabetically
    (roads are undirected).

    Raises ValueError if the record does not have this shape (missing hyphen or colon,
    empty or non-alphanumeric code, non-integer or negative length).

    Examples:
        parse_edge("BER-HAM:289") == ("BER", "HAM", 289)
        parse_edge("  MUC - NUE : 170 ") == ("MUC", "NUE", 170)
        parse_edge("HAM-BER:289") == ("BER", "HAM", 289)
    """
    line = line.strip()
    if '-' not in line:
        raise ValueError(f"Missing hyphen in record: {line}")

    left, right = line.split('-', 1)
    code1 = left.strip()

    if ':' not in right:
        raise ValueError(f"Missing colon in record: {line}")

    right_part, km_part = right.split(':', 1)
    code2 = right_part.strip()
    km_str = km_part.strip()

    # Validate depot codes
    if not code1 or not code1.isalnum():
        raise ValueError(f"Invalid depot code: {code1}")
    if not code2 or not code2.isalnum():
        raise ValueError(f"Invalid depot code: {code2}")

    # Validate and parse km
    if not km_str:
        raise ValueError("Missing road length")

    # Check for negative sign explicitly since int() might handle it but we want to reject negatives
    if km_str.startswith('-'):
        raise ValueError(f"Negative road length not allowed: {km_str}")

    try:
        km = int(km_str)
    except ValueError:
        raise ValueError(f"Invalid road length: {km_str}")

    if km < 0:
        raise ValueError(f"Negative road length not allowed: {km}")

    # Sort codes alphabetically to ensure undirected representation
    if code1 <= code2:
        return (code1, code2, km)
    else:
        return (code2, code1, km)
"
    }
  },
