      "content": "from __future__ import annotations

from typing import Dict, Iterable, List, Set, Tuple

from .build_adjacency import build_adjacency


def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str, int]]:
    """
    Find the roads whose closure would cut a region in two.

    Roads are undirected and the network is built with ``build_adjacency``. A road
    between depots ``a`` and ``b`` is critical if, once it is closed, ``b`` can no
    longer be reached from ``a``. Self-loops are never critical. Networks are small (a
    few dozen roads), so checking each road separately is fine.

    Returns the critical roads as ``(code_a, code_b, weight)`` triples with ``code_a < code_b``,
    sorted, each road listed once.
    """
    edge_list = list(edges)

    # Count edges between each pair of nodes (undirected)
    edge_counts: Dict[Tuple[str, str], int] = {}
    for u, v, _ in edge_list:
        if u == v:  # Skip self-loops
            continue
        a, b = (u, v) if u < v else (v, u)
        edge_counts[(a, b)] = edge_counts.get((a, b), 0) + 1

    critical: List[Tuple[str, str, int]] = []
    seen_critical: Set[Tuple[str, str, int]] = set()

    for u, v, w in edge_list:
        if u == v:  # Skip self-loops
            continue
        a, b = (u, v) if u < v else (v, u)

        # If there are multiple edges between a and b, none are critical
        if edge_counts[(a, b)] > 1:
            continue

        # Check if this specific edge (a, b, w) is already marked critical
        if (a, b, w) in seen_critical:
            continue

        # Build adjacency without edge (a, b)
        temp_adj = build_adjacency(edge_list, directed=False)
        # Remove the edge from both directions
        if a in temp_adj and b in temp_adj[a]:
            del temp_adj[a][b]
        if b in temp_adj and a in temp_adj[b]:
            del temp_adj[b][a]

        if not _is_connected(temp_adj, a, b):
            critical.append((a, b, w))
            seen_critical.add((a, b, w))

